import numpy as np
import ctypes, os
_lib=ctypes.CDLL(os.path.join(os.path.dirname(__file__),'emd_final.so'))
_f=_lib.auction
_f.argtypes=[ctypes.POINTER(ctypes.c_double),ctypes.c_int,ctypes.POINTER(ctypes.c_int)]
class Solver:
    def __init__(self):
        self.rows=np.arange(600)
    def solve(self,problem,**kwargs):
        M=problem['cost_matrix']
        if not (isinstance(M,np.ndarray) and M.dtype==np.float64 and M.flags.c_contiguous):
            M=np.ascontiguousarray(M,dtype=np.float64)
        n=M.shape[0]; a=np.empty(n,dtype=np.int32)
        _f(M.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),n,a.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
        G=np.zeros((n,n),dtype=np.float64); G[self.rows[:n],a]=1.0/n
        return {'transport_plan':G}

